/* @autogenerated */
import { TenantFilter, TenantProjection } from 'app/features/access/tenant/model/tenant.model';
import { TenantRepository } from 'app/features/access/tenant/repository/tenant-repository.service';
import { FormControl } from '@angular/forms';
import { Shift } from '@common/data/repository/repository.model';
import { input, effect, Component } from '@angular/core';

@Component({
  selector: 'tenant-view-list',
  templateUrl: './tenant-view-list.component.html',
  styleUrls: ['./tenant-view-list.component.scss'],
  standalone: false,
})
export class TenantViewListComponent {
  filters = input<TenantFilter>();
  actionName = input<string>('tenant');
  fixed = input<{ [key: string]: any }>();
  hidden = input<{ [key: string]: any }>();
  search = new FormControl<any>(undefined);
  list: Shift<TenantProjection[], TenantFilter>;

  constructor(repository: TenantRepository) {
    this.list = repository.projections([]);
    effect(() => {
      setTimeout(() => this.makeSearch());
    });
  }
  makeSearch() {
    const result = { limit: 10 } as any;
    const filter = this.search.value;
    const external = this.filters();
    if (external?.search) {
      result.search = external.search;
    }
    if (external?.name) {
      result.name = external.name;
    }
    if (filter?.search) {
      result.search = filter.search;
    }
    if (filter?.name) {
      result.name = filter.name;
    }
    if (filter?.order) {
      result.order = filter.order;
    }
    this.list.fetch(result);
  }

  next() {
    this.list.next();
  }

  reload() {
    this.list.reset();
  }

  prev() {
    console.log('PREV');
  }
}
